import random

import pytest
from PIL import Image

import lab5.random_flow_network as rfn_module
from lab5.random_flow_network import RandomFlowNetwork, draw_flow_network

SEEDS = range(20)
NS = [2, 3, 4]

# Test Generated by AI at my request 


@pytest.fixture(params=[(n, seed) for n in NS for seed in SEEDS])
def network(request) -> RandomFlowNetwork:
    """Swiezy obiekt dla danego N, z ustalonym ziarnem dla powtarzalnosci"""
    n, seed = request.param
    random.seed(seed)
    return RandomFlowNetwork(n)


def layer_of(network: RandomFlowNetwork) -> dict[int, int]:
    return {v: k for k, vertices in enumerate(network.layers) for v in vertices}


# __init__ / _initialize


@pytest.mark.parametrize("n", [-1, 0, 1])
def test_init_rejects_too_few_layers(n):
    with pytest.raises(ValueError, match="co najmniej 2"):
        RandomFlowNetwork(n)


def test_init_sets_empty_state():
    network = RandomFlowNetwork(3)
    assert network.N == 3
    assert network.s == network.t == 0
    assert network.layers == [(0,)]
    assert network.edges == []
    assert network.graph.is_directed()
    assert network.graph.vcount() == 0


# _generate_layers


def test_layers_count_and_ends(network):
    network._generate_layers()
    assert len(network.layers) == network.N + 2
    assert network.layers[0] == (network.s,)
    assert network.layers[-1] == (network.t,)


def test_inner_layers_have_2_to_N_vertices(network):
    network._generate_layers()
    for vertices in network.layers[1:-1]:
        assert 2 <= len(vertices) <= network.N


def test_layers_numbered_consecutively(network):
    network._generate_layers()
    all_vertices = [v for vertices in network.layers for v in vertices]
    assert all_vertices == list(range(network.t + 1))


# _generate_flow_edges


def test_flow_edges_go_to_next_layer(network):
    network._generate_layers()
    network._generate_flow_edges()
    layer = layer_of(network)
    for u, v in network.edges:
        assert layer[v] == layer[u] + 1


def test_flow_edges_every_vertex_has_out_and_in(network):
    network._generate_layers()
    network._generate_flow_edges()
    tails = {u for u, _ in network.edges}
    heads = {v for _, v in network.edges}
    for vertices in network.layers[:-1]:
        assert set(vertices) <= tails
    for vertices in network.layers[1:]:
        assert set(vertices) <= heads


def test_flow_edges_no_duplicates(network):
    network._generate_layers()
    network._generate_flow_edges()
    assert len(network.edges) == len(set(network.edges))


@pytest.mark.parametrize(
    "layers",
    [
        [(0,), (1, 2, 3, 4), (5, 6), (7,)],  # warstwa maleje
        [(0,), (1, 2), (3, 4, 5, 6), (7,)],  # warstwa rosnie
    ],
)
def test_flow_edges_when_layer_size_changes(layers):
    network = RandomFlowNetwork(4)
    network.layers = layers
    network.t = layers[-1][0]
    for seed in SEEDS:
        random.seed(seed)
        network.edges = []
        network._generate_flow_edges()
        tails = {u for u, _ in network.edges}
        heads = {v for _, v in network.edges}
        assert set(range(network.t)) <= tails
        assert set(range(1, network.t + 1)) <= heads


# _generate_random_edges


def run_until_random_edges(network: RandomFlowNetwork) -> list[tuple[int, int]]:
    network._generate_layers()
    network._generate_flow_edges()
    flow_edges = list(network.edges)
    network._generate_random_edges()
    return network.edges[len(flow_edges):]


def test_random_edges_count(network):
    assert len(run_until_random_edges(network)) == 2 * network.N


def test_random_edges_not_into_s_nor_out_of_t(network):
    for u, v in run_until_random_edges(network):
        assert v != network.s
        assert u != network.t


def test_random_edges_no_loops(network):
    for u, v in run_until_random_edges(network):
        assert u != v


def test_all_edges_unique_and_not_antiparallel(network):
    run_until_random_edges(network)
    edges = set(network.edges)
    assert len(edges) == len(network.edges)
    for u, v in edges:
        assert (v, u) not in edges


# _create_graph


def test_create_graph_matches_edges(network):
    graph = network.run()
    assert graph.vcount() == network.t + 1
    assert graph.get_edgelist() == network.edges


def test_create_graph_weights_in_range(network):
    graph = network.run()
    for weight in graph.es["weight"]:
        assert isinstance(weight, int)
        assert 1 <= weight <= 10


def test_create_graph_layer_attribute(network):
    graph = network.run()
    layer = layer_of(network)
    assert graph.vs["layer"] == [layer[v] for v in range(graph.vcount())]


def test_create_graph_labels(network):
    graph = network.run()
    assert graph.vs[network.s]["label"] == "s"
    assert graph.vs[network.t]["label"] == "t"
    others = [v["label"] for v in graph.vs if v.index not in (network.s, network.t)]
    assert all(label is None for label in others)


# run


def test_run_returns_own_graph(network):
    graph = network.run()
    assert graph is network.graph
    assert graph.is_directed()


def test_run_degrees_of_s_and_t(network):
    graph = network.run()
    assert graph.vs[network.s].indegree() == 0
    assert graph.vs[network.t].outdegree() == 0


def test_run_every_vertex_on_path_from_s_to_t(network):
    graph = network.run()
    from_s = set(graph.subcomponent(network.s, mode="out"))
    to_t = set(graph.subcomponent(network.t, mode="in"))
    assert from_s == to_t == set(range(graph.vcount()))


def test_run_twice_resets_state():
    random.seed(0)
    network = RandomFlowNetwork(3)
    network.run()
    graph = network.run()
    assert len(network.layers) == network.N + 2
    assert graph.vcount() == network.t + 1
    assert graph.ecount() == len(network.edges)
    assert len(set(network.edges)) == len(network.edges)


# draw_flow_network


def test_draw_returns_image_of_given_size(network):
    graph = network.run()
    image = draw_flow_network(graph, (600, 300))
    assert isinstance(image, Image.Image)
    assert image.size == (600, 300)


def test_draw_default_size(network):
    image = draw_flow_network(network.run())
    assert image.size == (900, 500)


def test_draw_positions_follow_layers(network, monkeypatch):
    captured = {}

    def fake_visualization(graph, positions, size):
        captured["positions"] = positions
        return Image.new("RGB", size)

    monkeypatch.setattr(rfn_module, "generate_visualization", fake_visualization)
    graph = network.run()
    width, height = 900, 500
    draw_flow_network(graph, (width, height))
    positions = captured["positions"]

    assert len(positions) == graph.vcount()
    for x, y in positions:
        assert 0 < x < width
        assert 0 < y < height

    for k, vertices in enumerate(network.layers):
        xs = {positions[v][0] for v in vertices}
        ys = [positions[v][1] for v in vertices]
        assert len(xs) == 1, "warstwa w jednej kolumnie"
        assert len(set(ys)) == len(ys), "wierzcholki warstwy nie nachodza na siebie"
        if k > 0:
            previous_x = positions[network.layers[k - 1][0]][0]
            assert xs.pop() > previous_x, "kolejne warstwy coraz dalej w prawo"
